  final Uint8List thumbhash;

  /// The original's local id when this device has it (tap to jump).
  final PlatformInt64? originalId;

  /// The original was deleted and this device holds the delete, so the quote
  /// shows "deleted message" instead of the snapshot (message-deletion:
  /// Deleting media and replies).
  final bool originalDeleted;

  const ReplyQuote({
    required this.to,
    required this.quote,
    required this.kind,
    required this.durationMs,
    required this.thumbhash,
    this.originalId,
    required this.originalDeleted,
  });

  @override
  int get hashCode =>
      to.hashCode ^
      quote.hashCode ^
      kind.hashCode ^
      durationMs.hashCode ^
      thumbhash.hashCode ^
      originalId.hashCode ^
      originalDeleted.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ReplyQuote &&
          runtimeType == other.runtimeType &&
          to == other.to &&
          quote == other.quote &&
          kind == other.kind &&
          durationMs == other.durationMs &&
          thumbhash == other.thumbhash &&
          originalId == other.originalId &&
          originalDeleted == other.originalDeleted;
}

@freezed
sealed class ReportKindInfo with _$ReportKindInfo {
  const ReportKindInfo._();

  /// A group/lobby message the admin already holds, referenced by group id and
  /// wire message id (both lowercase hex).
  const factory ReportKindInfo.group({
    /// The MLS group id, hex.
    required String groupId,

    /// The offending message's wire id, hex.
    required String msgId,
  }) = ReportKindInfo_Group;

  /// A DM message, with a capped quote of the offending text.
  const factory ReportKindInfo.dm({
    /// The quote of the offending message.
    required String quote,
  }) = ReportKindInfo_Dm;

  /// A whole user, with no message reference or quote.
  const factory ReportKindInfo.user() = ReportKindInfo_User;
}

/// A report the admin received, parsed from a report `Content.Text`
/// (moderation: The admin sees reports, change `report-and-block`).
class ReportView {
  /// The reported user.
  final UserRef reported;

  /// The reporter's short reason.
  final String reason;

  /// What the report points at.
  final ReportKindInfo kind;

  const ReportView({
    required this.reported,
    required this.reason,
    required this.kind,
  });

  @override
  int get hashCode => reported.hashCode ^ reason.hashCode ^ kind.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is ReportView &&
          runtimeType == other.runtimeType &&
          reported == other.reported &&
          reason == other.reason &&
          kind == other.kind;
}

@freezed
sealed class SendState with _$SendState {
  const SendState._();

  /// Stored; the server has not accepted it yet (⏳).
  const factory SendState.sending() = SendState_Sending;

  /// The server accepted it (✓).
  const factory SendState.accepted() = SendState_Accepted;

  /// The server rejected it.
  const factory SendState.failed({
    /// Why, for display.
    required String reason,
  }) = SendState_Failed;

  /// Held because this device is wedged behind the group's epoch and out of
  /// sync (group-membership: Orphaned device self-recovery). Its text is
  /// kept and sent once the device re-syncs: shown as waiting to re-sync, not
  /// a silent ⏳ and not failed.
  const factory SendState.outOfSync() = SendState_OutOfSync;
}

/// Which on-device engine produced a subject cutout (photo-sticker:
/// Segmentation seam and RGBA contract). The app passes the source its platform
/// plugin used; the core encodes every source identically, so this only names
/// the producer. Only the two MVP sources are exposed; `Server`/`OnnxLocal` are
/// reserved in the core for later.
enum StickerSource {
  /// iOS Vision foreground/subject mask.
  iosVision,

  /// Android ML Kit Subject Segmentation.
  androidMlKit,
}

/// A user id `<username>@<server_id>`.
class UserRef {
  /// The local part, chosen by the admin.
  final String username;

  /// The server's server id.
  final String serverId;

  const UserRef({required this.username, required this.serverId});

  @override
  int get hashCode => username.hashCode ^ serverId.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is UserRef &&
          runtimeType == other.runtimeType &&
          username == other.username &&
          serverId == other.serverId;
}

/// A video message (message-content: Video messages). No key and no blob id: they
/// stay in the core, which is given the message's local id.
class VideoView {
  /// Pixel width of the clip, for the bubble's aspect ratio.
  final int width;

  /// Pixel height of the clip, for the bubble's aspect ratio.
  final int height;

  /// The clip's length in milliseconds.
  final int durationMs;

  /// The first-frame ThumbHash blur to draw until the clip is downloaded.
  final Uint8List thumbhash;

  /// The clip's size on the server in bytes, to show before downloading.
  final BigInt size;

  /// The caption, only to be shown; its mentions are the message's
  /// `mentions`, as UTF-16 ranges of this text (message-content: Video caption
  /// and mentions).
  final String? caption;

  /// Where the clip is.
  final MediaStatus state;

  const VideoView({
    required this.width,
    required this.height,
    required this.durationMs,
    required this.thumbhash,
    required this.size,
    this.caption,
    required this.state,
  });

  @override
  int get hashCode =>
      width.hashCode ^
      height.hashCode ^
      durationMs.hashCode ^
      thumbhash.hashCode ^
      size.hashCode ^
      caption.hashCode ^
      state.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is VideoView &&
          runtimeType == other.runtimeType &&
          width == other.width &&
          height == other.height &&
          durationMs == other.durationMs &&
          thumbhash == other.thumbhash &&
          size == other.size &&
          caption == other.caption &&
          state == other.state;
}
